function ord(n){n=Math.round(n);let v=n%100,x=['th','st','nd','rd'];return n+(x[(v-20)%10]||x[v]||x[0])}
function fs(p,v){return p.played?(p.played.grade!=null?Number(p.played.grade).toFixed(1):'PLAYED'):p.out?'OUT':p.opp==='BYE'?'BYE':v==null?'\u2014':Number(v).toFixed(1)}
function sval(p){return p.played&&p.played.grade!=null?p.played.grade:p.start==null?-1:p.start}
function sv(p){return p.played&&p.played.grade!=null?`<span class="${grade(p.played.grade)}">${Number(p.played.grade).toFixed(1)}</span><span class="pdone">\u2713</span>`:p.out?'OUT':p.start==null?'\u2014':p.start}
function injChip(p){if(!p.inj||p.inj.avail>0.6)return '';let t=p.out?'OUT':p.inj.label==='Missed practice'?'DNP':'Q';return `<span class="injc ${p.out?'o':'q'}" title="${p.inj.label}${p.inj.note?' ('+p.inj.note+')':''}">${t}</span>`}
function pjT(p){return p.out?'OUT':p.played?'PLAYED':p.proj?p.proj.pts.toFixed(1):'\u2014'}
function vgNote(p,q){let v=q.vg;if(!v||!v.c)return '';let L={rec:['catches',1,.7],ryd:['receiving yards',.1,8],ruy:['rushing yards',.1,8],td:['touchdowns',6,.08],pyd:['passing yards',.04,15],ptd:['passing TDs',4,.15]},
 d=v.c.map(c=>{let l=L[c[0]];return l?{t:l[0],m:c[1],v:c[2],pts:Math.abs((c[2]-c[1])*l[1]),big:Math.abs(c[2]-c[1])>=l[2],f:c[0]==='td'||c[0]==='ptd'?2:0}:null}).filter(x=>x&&x.big).sort((a,b)=>b.pts-a.pts).slice(0,2),
 why=d.length?d.map(x=>`${x.t} ${x.v.toFixed(x.f)} on the sportsbooks vs ${x.m.toFixed(x.f)} from usage`).join('; '):'in line with the sportsbooks';
 return `<div class="projNote vgn"><b>Vegas lines included.</b> From usage alone: ${v.pre.toFixed(1)}. Sportsbook lines imply ${v.v.toFixed(1)}. Blended: <b>${q.pts.toFixed(1)}</b>. ${d.length?'Biggest gaps: ':'Right now he is '}${why}.</div>`}
function projBox(p,q,line,title){let top=Math.max(q.hi*1.06,20),L=q.lo/top*100,W=(q.hi-q.lo)/top*100,M=q.pts/top*100,av=p.inj?p.inj.avail:1,risk=av<1&&p.pos!=='QB'?`<div class="projNote">${p.inj.label}: about ${Math.round(av*100)}% to play. Weighed for injury risk: <b>${(q.pts*av).toFixed(1)}</b>.</div>`:'',fx=(k,l)=>{let v=q.fx[k];return `<div class="pfx"><b class="${v>0.4?'good':v<-0.4?'bad':'muted'}">${Math.abs(v)<0.05?'0.0':sg(v)}</b><span>${l}</span></div>`};let dt=null;try{dt=typeof dvTier==='function'?dvTier(p.opp,p.pos):null}catch(e){}let mu=`<div class="pjMu"><div class="pjT">${tlogo(p.team,'big')}<b>${p.team}</b></div><div class="pjV">VS<small>PPR</small></div><div class="pjT">${tlogo(p.opp,'big')}<b>${p.opp}</b></div></div>`+(dt?`<div class="pjTier ${dt.cls}">${dt.cls==='g'?'Easy':dt.cls==='r'?'Tough':'Average'} matchup \u2022 ${p.opp} is #${dt.rk} in points allowed to ${p.pos}s</div>`:'');return `<div class="panel projBox"><div class="ph">${title}</div>${mu}<div class="projTop"><div class="projNum">${q.pts.toFixed(1)}</div><div class="projTxt"><b>projected points</b><span>${line}</span></div></div><div class="projBar"><i style="left:${L}%;width:${W}%"></i><u style="left:${M}%"></u></div><div class="projRng"><span>Floor ${q.lo.toFixed(1)}</span><span>4 of 5 games land here</span><span>Ceiling ${q.hi.toFixed(1)}</span></div>${risk}${q.adj?`<div class="projNote">Our adjustment: <b>${q.adj.pts>0?'+':''}${q.adj.pts}</b> pts. ${trEsc(q.adj.note||'')}</div>`:''}${vgNote(p,q)}<div class="projFx">${fx('script','Game script')}${fx('matchup','Matchup')}${fx('inj','Injuries')}</div><details class="how"><summary>How this is built</summary><div class="explain">Recent and last-season usage, the Vegas spread and total, how this defense treats his position, and the injury report (teammates out${p.pos==='QB'?', receivers out':', QB out'}). The three boxes show how many points each moved it. When sportsbook player lines are posted (Wednesday to Sunday) they are blended in, leaning on them most for new starters and players with few games. PPR scoring only${p.pos==='QB'?'; QBs get 4 per passing TD, 1 per 25 yards, -2 per INT':''}. Tested on past seasons it is about ${p.pos==='QB'?'10':'5'}% closer than a plain season average.</div></details></div>`}
function projHTML(p){let q=p.proj;if(!q||p.out||p.played||p.opp==='BYE')return '';return projBox(p,q,`${p.pos==='QB'?'':(p.pos==='RB'||q.car>=1?`<b>Rushing</b> ${q.car} carries, <b>${Math.round(q.ruy)} yds</b> • `:'')+`<b>Receiving</b> ${q.tgt} targets, ${q.rec.toFixed(1)} catches, <b>${Math.round(q.ryd)} yds</b> • `}${q.td.toFixed(2)} TD`,'Week '+META.next_week+' projection')}
function qbHTML(p){let out='';if(p.played){let q=p.played,d=p.proj?q.ppr-p.proj.pts:null;out+=`<div class="injBox playedBox qbCard"><div class="injHd">\u2713 Final \u2022 Week ${q.wk}</div><div class="injRow ${d==null||d>=0?'up':'o'}"><b>${resTxt(q)}</b> vs ${q.opp} \u2022 scored <b>${q.ppr}</b> PPR${d!=null?` (projected ${p.proj.pts.toFixed(1)}, ${d>=0?'+':''}${d.toFixed(1)})`:''}</div><div class="injRow q">${q.comp}/${q.att}, ${q.pyd} yds, ${q.ptd} TD, ${q.int} INT${q.ruy?', '+q.ruy+' rush yds':''}${q.rtd?', '+q.rtd+' rush TD':''}</div></div>`}let q=p.proj;if(!q)return out+injHTML(p);if(!p.played)out+=projBox(p,q,`${q.pyd} pass yds, ${q.ptd.toFixed(1)} pass TD, ${q.int.toFixed(1)} INT \u2022 ${q.ruy} rush yds`,'Week '+META.next_week+' projection');return out+(p.sub?'<div class="projNote">Starter is out, so this is the backup (starter\'s volume, a little lower).</div>':'')+injHTML(p)}
function pv(p){return p.out?-1:p.played?p.played.ppr:p.proj?p.proj.pts:-2}
function heroPj(p){if(p.played){let q=p.played,d=q.proj!=null?q.ppr-q.proj:null;return `<div class="heroPj">Projected <b>${q.proj!=null?q.proj.toFixed(1):'\u2014'}</b> \u2192 scored <b class="${d==null?'':d>=0?'good':'bad'}">${q.ppr}</b> PPR</div>`}if(p.out||!p.proj||p.opp==='BYE')return '';return `<div class="heroPj pjGo" role="button" tabindex="0" data-pjid="${p.id}" title="See where he sits in the Week ${META.next_week} projections">Week ${META.next_week} projection <b>${p.proj.pts.toFixed(1)}</b> PPR <span class="pjArr">&#8250;</span></div>`}
function resTxt(q){let m=/(\d+), \w+ (\d+)/.exec(q.score||'');return m?`${q.res} ${m[1]}-${m[2]}`:q.res}
function playedHTML(p){let q=p.played;if(!q)return '';let d=q.proj!=null?q.ppr-q.proj:null;return `<div class="injBox playedBox"><div class="injHd">\u2713 Final \u2022 Week ${q.wk}</div><div class="injRow ${d==null||d>=0?'up':'o'}"><b>${resTxt(q)}</b> vs ${q.opp} \u2022 scored <b>${q.ppr}</b> PPR${q.proj!=null?` (projected ${q.proj.toFixed(1)}, ${d>=0?'+':''}${d.toFixed(1)})`:''}</div><div class="injRow q">${q.rec} catches on ${q.tgt} targets, ${q.ry} yds${q.car?', '+q.car+' carries, '+q.ruy+' yds':''}${q.td?', '+q.td+' TD':''}${q.snap!=null?' \u2022 '+q.snap+'% snaps':''}${q.grade!=null?' \u2022 graded '+Number(q.grade).toFixed(1):''}. ${q.counted?'Counted in his Mania Rating.':'Not in his Mania Rating yet (waiting on NFL data).'}</div></div>`}
function injHTML(p){let wk=META.next_week,o=[],pm=x=>(x>0?'+':'')+x.toFixed(1);
 (p.inj_why||[]).forEach(w=>{o.push(w.kind==='depth'?`<div class="injRow ${w.pts>0?'up':'q'}"><b>Depth chart</b> (${w.s}) ${pm(w.pts)} • ${w.pts>0?'first up at his position':'someone is now ahead of him'}</div>`:w.kind==='qb'?`<div class="injRow ${w.pts<0?'q':'up'}"><b>${w.n}</b> (QB, ${w.s}) ${pm(w.pts)} • passing game takes a hit</div>`:`<div class="injRow up"><b>${w.n}</b> (${w.pos}, ${w.s}) ${pm(w.pts)} • ${w.ev?`without him that work was worth ${w.ev.without} pts vs ${w.ev.with} with (${w.ev.games} game${w.ev.games>1?'s':''})`:'his work shifts to teammates'}</div>`)});
 if(!p.inj&&!o.length)return '';
 let pen=p.inj?(4*(1-p.inj.avail)).toFixed(1):0,rt=p.inj&&p.inj.ret?(p.inj.rw>17?' • Out for the season (ESPN)':' • Est. return '+['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'][+p.inj.ret.slice(5,7)-1]+' '+(+p.inj.ret.slice(8,10))+(p.inj.rw<=17?' (Week '+p.inj.rw+', ESPN)':'')):'',
  head=p.inj?`<b>${p.inj.label}</b>${p.inj.note?' ('+p.inj.note+')':''} • ${p.out?'no Week '+wk+' Rating':'Rating -'+pen}${rt}`:`Teammate injuries shift his Week ${wk} Rating`,dot=`<span class="injDot ${p.out?'o':p.inj?'q':'up'}"></span>`;
 if(!o.length)return `<div class="injMini"><div class="injLine" style="display:flex;align-items:center;gap:8px;font-size:13px;padding:8px 12px;color:#33445f">${dot}<span>${head}</span></div></div>`;
 return `<details class="injMini"><summary>${dot}<span>${head}</span><span class="injMore">${o.length} teammate note${o.length>1?'s':''} ▾</span></summary><div class="injBody">${o.join('')}${META.injuries&&META.injuries.updated?'<div class="injUp">Injury report updated '+META.injuries.updated+'</div>':''}</div></details>`}
function outlook(p,start){
 if(p.played)return {t:'Played: '+p.played.ppr+' PPR',d:'',c:'g70',r:997};
 if(p.opp==='BYE')return {t:'On bye',d:'',c:'g0',r:999};
 if(p.out)return {t:'OUT',d:'',c:'g0',r:998};
 let a=(REFS[p.pos]||{}).start||[],r=Math.abs(start-p.start)<1e-9?p.start_pos_rank:Math.max(1,1+a.filter(x=>x>start+.0005).length-(p.start>start?1:0)),lim=p.pos==='TE'?[6,12]:[12,24];
 return {t:p.pos+r+' this week',d:'',c:r<=lim[0]?'g90':r<=lim[1]?'g70':'g0',r}
}
function badges(p,idxs){
 let L=idxs.map(i=>p.logs[i]).filter(Boolean);if(!L.length)return [];
 let c=calc(p,idxs),M=c.M,P=k=>percentile(p.pos,k,M[k]),tg=sum(L,'tgt'),rc=sum(L,'rec'),ry=sum(L,'ry'),air=sum(L,'air'),adot=tg?air/tg:0,ypr=rc?ry/rc:0,pp=L.map(x=>x.ppr),mu=pp.reduce((x,y)=>x+y,0)/pp.length,sd=Math.sqrt(pp.reduce((x,y)=>x+(y-mu)*(y-mu),0)/pp.length),cv=mu>0?sd/mu:0,tdp=sum(L,'ppr')>0?6*(sum(L,'rtd')+sum(L,'rutd'))/sum(L,'ppr'):0,tr=p.trend_pct||0,o=[],add=(n,d,s,m)=>o.push({n,d,s,m});
 let pc=P('carries_pg'),pt=P('targets_pg'),ps=P('snap_pct'),pts=P('touch_share'),pgl=P('gl_carries_pg'),prz=P('rz_targets_pg'),ptsh=P('target_share'),pcr=P('catch_rate'),pyc=P('yards_per_carry'),pair=P('air_share');
 if(p.pos==='RB'){
  if(pc>=60&&pt>=60&&ps>=70)add('Three-Down Back','Runs, catches and stays on the field.',(pc+pt+ps)/3+8);
  if(pc>=70&&pts>=70)add('Workhorse','Big carry load and a big share of the team\u2019s touches.',(pc+pts)/2+5);
  if(pt>=75&&pc<=65)add('Pass-Catcher','Gets his work through the air more than on the ground.',pt);
  if(pgl>=75)add('Goal-Line Hammer','Gets the carries inside the 5.',pgl);
  if(pyc>=80&&M.carries_pg>=5)add('Home Run Hitter','Big yards every time he carries it.',pyc-5);
  if(tdp>=.4&&sum(L,'ppr')>0)add('TD Dependent','A big part of his points come from touchdowns.',60);
  if(pts<=55&&ps<=60)add('Committee Back','Shares the backfield work.',45);
  if(ps<=30)add('Change of Pace','Used in short bursts, not every down.',35);
  if(!o.length)add('Depth Back','Part of the rotation without a standout role.',10);
 }else if(p.pos==='WR'){
  if(ptsh>=85)add('Target Hog','A huge share of the team\u2019s targets run through him.',ptsh+5);
  if(adot>=11&&pair>=60)add('Deep Threat','Gets targets downfield and a big share of the air yards.',pair);
  if(adot<=8&&pcr>=60&&pt>=50)add('Short-Game Specialist','Short targets, catches most of them, PPR-friendly.',pcr);
  if(prz>=80)add('Red-Zone Weapon','Targeted near the goal line at a high rate.',prz);
  if(ypr>=14.5&&rc>=6)add('Big-Play Threat','Piles up yards on his catches.',70);
  if(L.length>=3&&cv>=.55)add('Boom or Bust','His weekly points swing a lot.',50);
  if(tr>=20)add('Rising Role','His recent targets are well up from his season average.',55);
  if(tr<=-20)add('Fading Role','His recent targets are well down from his season average.',40);
  if(!o.length)add('Role Player','Contributes without a standout trait yet.',10);
 }else{
  if(ptsh>=85)add('Featured Tight End','A real share of the offense runs through him.',ptsh+5);
  if(adot>=9.5)add('Seam Stretcher','Runs deeper routes than most tight ends.',70);
  if(adot<=6.5&&pcr>=55&&pt>=45)add('Safety Blanket','Short, steady targets for the quarterback.',pcr);
  if(prz>=80)add('Red-Zone Target','The team looks for him near the goal line.',prz);
  if(ps>=65&&pt<=30)add('Blocking Tight End','On the field a lot, but not much in the passing game.',30);
  if(tr>=20)add('Rising Role','His recent targets are well up from his season average.',55);
  if(tr<=-20)add('Fading Role','His recent targets are well down from his season average.',40);
  if(!o.length)add('Role Player','Contributes without a standout trait yet.',10);
 }
 {let A_=p.adv;if(A_&&p.pos!=='QB'){let nm=p.pos==='RB'?'backs':p.pos+'s',ord=v=>{let t=['th','st','nd','rd'],w=v%100;return v+(t[(w-20)%10]||t[w]||t[0])},nd=A_.n_dr,nb=A_.n_btr,nc=A_.n_btc,ny=A_.n_yacc,nyr=A_.n_yacr;
  if(A_.q_rec&&A_.dr_rk){if(A_.drops>=2&&A_.dr_rk>=nd*.88)add('Butterfingers',A_.drops+' drops on '+A_.tgt+' targets ('+A_.dr_raw.toFixed(1)+'%), the '+ord(nd-A_.dr_rk+1)+'-worst drop rate among '+nd+' '+nm+'.',78+20*A_.dr_rk/nd,A_.drops>=3&&A_.dr_rk>=nd*.93);
   else if(A_.tgt>=22&&(A_.drops===0||A_.dr_rk<=nd*.1))add('Sure Hands','Dropped '+A_.drops+' of '+A_.tgt+' targets ('+A_.dr_raw.toFixed(1)+'%), the '+ord(A_.dr_rk)+'-best drop rate among '+nd+' '+nm+'.',66)}
  if(p.pos!=='RB'&&A_.q_rec&&A_.btr_rk){if(A_.bt_rec>=3&&A_.btr_rk<=Math.ceil(nb*.08))add('Tackle Breaker',A_.bt_rec+' broken tackles on '+A_.rec+' catches, the '+ord(A_.btr_rk)+'-best rate among '+nb+' '+nm+'.',68);
   if(A_.rec>=8&&A_.yacr_rk&&A_.yacr_rk<=Math.ceil(nyr*.1))add('YAC Machine',A_.yacr_raw.toFixed(1)+' yards after the catch per reception, '+ord(A_.yacr_rk)+' among '+nyr+' '+nm+'.',64)}
  if(p.pos==='RB'&&A_.q_ru){if(A_.bt_ru>=4&&A_.btc_rk<=Math.ceil(nc*.12))add('Tackle Breaker',A_.bt_ru+' broken tackles on '+A_.car_pfr+' carries ('+A_.btc_raw.toFixed(1)+'%), '+ord(A_.btc_rk)+' among '+nc+' backs.',74);
   if(A_.car_pfr>=30&&A_.yacc_rk<=Math.ceil(ny*.12))add('Contact Winner',A_.yacc_raw.toFixed(1)+' yards after contact per carry, '+ord(A_.yacc_rk)+' among '+ny+' backs.',70);
   if(A_.car_pfr>=30&&A_.yacc_rk>=ny*.88)add('Goes Down Easy','Only '+A_.yacc_raw.toFixed(1)+' yards after contact per carry, the '+ord(ny-A_.yacc_rk+1)+'-lowest among '+ny+' backs.',72,A_.yacc_rk>=ny*.94);
   else if(A_.car_pfr>=30&&A_.ybcc_rk<=nc*.25&&A_.yacc_rk>=ny*.65)add('Line Dependent','Most of his yards come before contact, so the blocking is doing the work.',55);
   if(A_.dr_rk&&A_.tgt>=10&&A_.drops>=2&&A_.drops/A_.tgt>=.15)add('Butterfingers',A_.drops+' drops on '+A_.tgt+' targets out of the backfield.',70)}
  if(A_.fum>=2)add('Fumble Prone',A_.fum+' fumbles lost this season.',74,A_.fum>=3)}}
 let n=c.mania>=93?5:c.mania>=88?4:c.mania>=80?3:c.mania>=65?2:1;o.sort((x,y)=>y.s-x.s);let pk=o.slice(0,n);o.filter(b=>b.m&&!pk.includes(b)).slice(0,2).forEach((b,i)=>{pk[pk.length-1-i]=b});return pk
}
