  let adj=((c?c.match.adj:p.matchup_adj)||0),sg=adj>=0?'+':'',rows=defenseVs(p.pos).slice().sort((a,b)=>b.pg-a.pg),ix=rows.findIndex(x=>x.team===p.opp),tag=adj>=1?['Good matchup','up']:adj<=-1?['Tough matchup','dn']:['Neutral matchup',''];
