 let ctl=`<div class="tcCtl"><div class="tseg" data-g="lm"><button type="button" class="tsb${TLM==='week'?' on':''}" data-v="week">Week ${META.next_week}</button><button type="button" class="tsb${TLM==='best'?' on':''}" data-v="best">Best</button></div><div class="tseg" data-g="scope">${[['starters','Starters'],['all','+ Bench']].map(([k,l])=>`<button type="button" class="tsb${teamScope===k?' on':''}" data-v="${k}">${l}</button>`).join('')}</div></div>`;
