 box.querySelectorAll('.tsample').forEach(b=>b.onclick=fillSample);let tb=box.querySelector('.tbest');if(tb)tb.onclick=()=>{tBestLineup('A');tBestLineup('B');tSub=null;saveTeams();renderTeams()};
