 box.querySelectorAll('.tcSel').forEach(sel=>sel.onchange=()=>{let side=sel.dataset.side,v=sel.value;if(v==='me'){tLoadTeam(side,TR.my,TR.tname||'My team')}else if(/^L\d+$/.test(v)){let o=TR.lg[+v.slice(1)];if(o)tLoadTeam(side,o.ids,o.n)}else if(v==='blank'){TM[side]=newTeam(side==='A'?'My team':'Their team');tEnsure(TM[side])}else if(v==='sample'){fillSample();return}TM[side].lsrc=v;saveTeams();renderTeams()});
