 /* your own team is the one with no "Propose Trade" button */
 teams.forEach((T,k)=>{let end=k+1<teams.length?teams[k+1].i0-1:L.length;T.prop=L.slice(T.i0,end).some(x=>x.indexOf('Propose Trade')>=0)});
