function lgStand(){let kd=kdAdd(),wk=META.next_week,all=[{n:TR.tname||'Your team',ids:TR.my,me:true,i:-1}].concat(TR.lg.map((t,i)=>({n:t.n,ids:t.ids,i,t}))),
 rows=all.map(t=>{let L=trLineup(t.ids,'later'),pace=L.st.reduce((s,x)=>s+(x.v&&x.v.p.m&&x.v.p.m.ppr!=null?+x.v.p.m.ppr:0),0)+kdAdd(t.ids,'ppg'),rc=lgRecOf(t.t||{n:t.n},t.me);return {n:t.n,me:t.me,i:t.i,w:rc?rc.w:null,l:rc?rc.l:null,tt:rc?rc.t:0,pace,wkp:trLineupWD(t.ids,wk).tot+kdAdd(t.ids,wk)}}),
 hasRec=rows.every(r=>r.w!=null),pct=r=>(r.w+(r.tt||0)/2)/Math.max(1,r.w+r.l+(r.tt||0));
 rows.sort((a,b)=>hasRec?(pct(b)-pct(a)||b.pace-a.pace):b.pace-a.pace);
 let rk=(f)=>{let o=rows.slice().sort((a,b)=>f(b)-f(a)),m={};o.forEach((r,i)=>m[r.n]=i+1);return m};
 return {rows,hasRec,rkPace:rk(r=>r.pace),rkWk:rk(r=>r.wkp)}}
function lgLetter(pc){let G=[[.93,'A+'],[.85,'A'],[.77,'A-'],[.68,'B+'],[.58,'B'],[.48,'B-'],[.38,'C+'],[.28,'C'],[.18,'C-'],[.1,'D']];for(let i=0;i<G.length;i++)if(pc>=G[i][0])return G[i][1];return 'F'}
var LGR={sort:'g',key:'',rows:[]};
function lgRankRows(){let c=trCtx(),kd=kdAdd(),wk=META.next_week,key=JSON.stringify([TR.my,TR.lg,c.key,kd,wk]);if(LGR.key===key)return LGR.rows;
 let all=[{n:TR.tname||'Your team',ids:TR.my,me:true,i:-1}].concat(TR.lg.map((t,i)=>({n:t.n,ids:t.ids,i}))),
 rows=all.map(t=>{let L=trLineup(t.ids,'later'),ms=L.st.filter(x=>x.v&&x.v.p.mania!=null).map(x=>+x.v.p.mania);return {n:t.n,me:t.me,i:t.i,tot:L.tot,mania:ms.length?ms.reduce((a,b)=>a+b,0)/ms.length:null,wkp:trLineupWD(t.ids,wk).tot+kdAdd(t.ids,wk),ppg:L.st.reduce((s,x)=>s+(x.v&&x.v.p.m&&x.v.p.m.ppr!=null?+x.v.p.m.ppr:0),0)+kdAdd(t.ids,'ppg')}}),N=rows.length;
 rows.slice().sort((a,b)=>b.tot-a.tot).forEach((r,k)=>{r.rk=k+1;r.pc=N>1?(N-1-k)/(N-1):.5;r.g=lgLetter(r.pc)});
 [['rkM',r=>r.mania||0],['rkW',r=>r.wkp],['rkP',r=>r.ppg]].forEach(([k,f])=>rows.slice().sort((a,b)=>f(b)-f(a)).forEach((r,i)=>r[k]=i+1));LGR={sort:LGR.sort,key,rows};return rows}
function lgRankChipHTML(name){if(!lgOn()||!name||!TR.my.length)return '';let R=lgRankRows(),nm=String(name).toLowerCase(),r=R.find(x=>x.n.toLowerCase()===nm);if(!r)return '';return `<div class="lgRkChip"><span>In your league</span><b>Mania #${r.rkM}</b><b>Week ${META.next_week} #${r.rkW}</b><b>Season avg #${r.rkP}</b><small>of ${R.length}</small></div>`}
