 var OFF=['QB','RB','FB','WR','TE','LT','LG','C','RG','RT'],TTL={QB:'Quarterbacks',RB:'Running backs',FB:'Fullbacks',WR:'Wide receivers',TE:'Tight ends',LT:'Left tackle',LG:'Left guard',C:'Center',RG:'Right guard',RT:'Right tackle'};
 var STARTN={WR:3};
