 document.getElementById('dcSeg').onclick=function(e){var b=e.target.closest('button[data-s]');if(!b)return;sec=b.dataset.s;document.querySelectorAll('#dcSeg button').forEach(function(x){x.classList.toggle('on',x===b)});draw()};
