function kdVsHTML(p){var r=p.r,isK=r.pos==='K',opp=r.opp;if(!opp||r.bye)return '';var src=isK?KDX.k:KDX.d,A=[];(src||[]).forEach(function(x){(x.log||[]).forEach(function(l){if(l.opp===opp)A.push([x,l])})});if(!A.length)return '';A.sort(function(a,b){return b[1].pts-a[1].pts});var t=kdTier(r.pos,opp),nm=isK?'kickers':'defenses';
 var C=isK?[['FG',function(l){return l.fg}],['XP',function(l){return l.xp}],['Long',function(l){return l.lg||'—'}]]:[['Pts allowed',function(l){return l.pa}],['Yards',function(l){return l.ya}],['Sacks',function(l){return l.sk}],['Takeaways',function(l){return l.int+l.fr}],['TD',function(l){return l.td}]];
 var tr=A.map(function(a,i){var x=a[0],l=a[1],q=kdPl(x.id),me=x.id===r.id;return '<tr class="'+(me?'vsMe ':'')+(i<6?'':'vx')+'"><td class="vsPl"><span class="vsAv" style="--s:'+Math.round(x.rating||0)+';--c:'+ring(x.rating||0)+'">'+(q?pic(q):'')+'</span><span class="vsNm"><span class="playerlink" data-kd="'+x.id+'">'+trEsc(x.name)+'</span><small>'+(x.team||'')+' • Wk '+l.w+'</small></span></td><td class="r vsP"><b>'+l.pts+'</b></td>'+C.map(function(c){return '<td class="r">'+c[1](l)+'</td>'}).join('')+'</tr>'}).join('');
 return '<div class="panel vsBox"><div class="ph">How '+nm+' did against '+opp+'</div>'+(t?'<p class="vsSum"><b>'+t.v.toFixed(1)+'</b> fantasy points a game given up to '+nm+', <b>'+ord(t.rk)+'</b> most of '+t.n+'.</p>':'')+'<div class="tablewrap"><table class="vsT vsT2"><thead><tr><th>'+(isK?'Kicker':'Defense')+'</th><th class="r">Pts</th>'+C.map(function(c){return '<th class="r">'+c[0]+'</th>'}).join('')+'</tr></thead><tbody>'+tr+'</tbody></table></div>'+(A.length>6?'<button type="button" class="vsMore" data-n="'+(A.length-6)+'">Show all '+A.length+' games</button>':'')+'</div>'}
(function(){var o=openKDP;openKDP=function(p){var res=o.apply(this,arguments);try{var r=p.r,pb=document.getElementById('profileBody'),isK=r.pos==='K';pb.querySelectorAll('.scorebig').forEach(function(e){if(e.textContent==='100.0')e.textContent='100'});
 var panels=pb.querySelectorAll(':scope>.panel'),gp=null;panels.forEach(function(x){var h=x.querySelector('.ph');if(h&&h.textContent==='Game log')gp=x});
 if(gp){var rows=gp.querySelectorAll('tbody tr'),L=r.log.slice().reverse();rows.forEach(function(tr,i){var l=L[i],td=tr.querySelector('td');if(!l||!td)return;td.innerHTML='W'+l.w+' '+kdChip(r.pos,l.opp,'vs')+(isK?'':' <span class="muted">'+l.res+'</span>')});
  var lg=document.createElement('div');lg.className='oppLg';lg.innerHTML='<span>Opponent color:</span><span class="oppC g">Easy for '+(isK?'kickers':'defenses')+'</span><span class="oppC y">Average</span><span class="oppC r">Tough</span>';gp.appendChild(lg)}
 var h=kdVsHTML(p);if(h){var d=document.createElement('div');d.innerHTML=h;var el=d.firstChild,g2=pb.querySelector('.grid2');if(g2)g2.parentNode.insertBefore(el,g2.nextSibling);else pb.appendChild(el);
  el.querySelectorAll('[data-kd]').forEach(function(x){x.onclick=function(){var q=kdPl(x.dataset.kd);if(q)openKDP(q)}});var mb=el.querySelector('.vsMore');if(mb)mb.onclick=function(){el.classList.toggle('all');mb.textContent=el.classList.contains('all')?'Show fewer':'Show all '+(+mb.dataset.n+6)+' games'}}
 }catch(e){console.error(e)}return res}})();

function trKdRows(ids,w,mt,sc){if(!KD.on||sc==='bench')return '';var T=kdTeam(ids,w),h='',FUT=w>META.next_week;
 function one(r,slot,lab,av){if(!r){return '<div class="tslot trTs empty2"><span class="tpos">'+slot+'</span><span></span><div class="tnm"><b>No '+lab+' on this roster</b><small>Counted as the league average</small></div><div class="tv">'+(FUT||mt==='mania'?'':av.toFixed(1))+'</div></div>'}
  var p=kdPl(r.id),val=mt==='mania'?(r.rating==null?'\u2014':r.rating.toFixed(1)):mt==='avg'?r.ppg.toFixed(1):(FUT?'\u2014':(function(){var x=kdWk(r,w);return x==null?'\u2014':(+x).toFixed(1)})()),opp=r.bye?'Bye':(r.opp?(r.home?'vs ':'at ')+r.opp:'');
  return '<div class="tslot trTs"><span class="tpos">'+slot+'</span>'+thumb(p)+'<div class="tnm"><b class="tlink" data-kdopen="'+r.id+'">'+trEsc(r.name)+'</b><small>'+r.team+' \u2022 '+(r.pos==='K'?'K':'D/ST')+(opp?' \u2022 '+opp:'')+'</small></div><div class="tv'+(mt==='mania'&&r.rating!=null?' '+grade(r.rating):'')+'">'+val+'</div></div>'}
 var av=kdAvg();if(T.kon)h+=one(T.k,'K','kicker',av.k);if(T.don)h+=one(T.d,'D/ST','defense',av.d);return h}
