 var raw=.35*b.Production+.15*b.Passing+.12*b.Rushing+.13*b.Scoring+.25*b.Efficiency,q=R.raw,lt=0,eq=0;q.forEach(function(v){if(v<raw)lt++;else if(v===raw)eq++});
 var pc=Math.max(0,Math.min(1,(lt+.5*eq)/Math.max(q.length,1))),lad=R.lad,base;if(lad.length>10){var pos=pc*(lad.length-1),f=Math.floor(pos),c=Math.min(lad.length-1,f+1);base=lad[f]+(lad[c]-lad[f])*(pos-f)}else base=45+.52*raw;
