/* ---------- standings by place (1st, 2nd, 3rd ...), deep finder ---------- */
function trOrdS(n){var s=['th','st','nd','rd'],v=n%100;return n+(s[(v-20)%10]||s[v]||s[0])}
function trLbl(f){return f<=.15?'top':f<=.35?'upper':f<=.55?'bub':f<=.8?'low':'bot'}
function trPlaceTeam(name){var A=TR.lgAll||[];if(A.length<3||!name)return null;var i=A.findIndex(function(t){return t.n===name});if(i<0)return null;var pt=A.map(function(t){var g=(t.w||0)+(t.l||0)+(t.t||0);return g?((t.w||0)+.5*(t.t||0))/g:0}),g0=(A[i].w||0)+(A[i].l||0);if(g0<3)return null;return pt.filter(function(x){return x>pt[i]}).length+1}
function trPlace(side){var m=(TR.stand||{})[side];if(m&&m!=='auto'){var o={top:2,upper:4,bub:5,low:8}[m],n=o||+m;if(n)return Math.min(n,TR.n)}
 var nm=side==='my'?TR.tname:(TR.lg&&TR.lg[TR.lgi]&&TR.lg[TR.lgi].n),p=trPlaceTeam(nm);if(p)return p;var r=(TR.rec&&TR.rec[side])||[0,0],g=r[0]+r[1];if(g<3)return null;var q=(r[0]+1.5)/(g+3),z=Math.min(.95,Math.max(.05,(q-.2)/.6));return Math.max(1,Math.min(TR.n,Math.round(1+(1-z)*(TR.n-1))))}
