(function(){var o=trRow;trRow=function(id,btns,note,tag){var h=o(id,btns,note,tag),v=trCtx().V[id];if(!v||!v.p.logs)return h;var g=v.p.logs.filter(function(l){return l.snap!=null&&!l.auto&&l.weight!==0});if(g.length<5)return h;var a=g.reduce(function(s,l){return s+l.snap},0)/g.length,r=g.slice(-3),b=r.reduce(function(s,l){return s+l.snap},0)/r.length;if(Math.abs(b-a)<8)return h;return h.replace('</small>','<i class="trTag '+(b>a?'up':'dn')+'" title="Snap share the last 3 games vs the season">Role '+(b>a?'▲':'▼')+'</i></small>')}})();
