function trDeepKey(){return JSON.stringify([TRF.auto?1:0,TRF.nb,TRF.sl,TR.give,TR.my,TR.lock,TRF.team,trPlace('my'),TR.lg.map(function(t){return t.ids.length+t.n})])}
